//! Contract tests: drift between the Rust types and a generated consumer is a build failure.
//!
//! * the committed generated files are exactly what the generator writes now;
//! * the app definitions declare the `app` API that the Lua adapter installs (and nothing of the view tree a host
//!   used to draw), offer exactly the modules the host does (no more, no refused one) and carry one `declare require`;
//! * the TypeScript output declares every wire type the shell reads and every method of the table.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)] // integration-test helpers

use std::path::Path;

use vos_domain::{protocol::METHODS, GLOBALS_NOT_FOR_APPS, NOT_FOR_APPS};

fn root() -> &'static Path {
    vos_codegen::repo_root()
}

/// The schema the declarations are written from.
fn schema() -> mlua_ir::ir::Ir {
    vos_lua::declarations::schema()
}

/// The app definitions the generator writes now.
fn definitions() -> String {
    vos_codegen::apps::luau(&schema()).unwrap()
}

/// The TypeScript declarations the generator writes now.
fn typescript_declarations() -> String {
    vos_codegen::apps::typescript(&schema()).unwrap()
}

// ---- the generated files ----------------------------------------------------------------------------------

#[test]
fn the_committed_generated_files_are_up_to_date() {
    let stale = vos_codegen::stale(root());
    assert!(stale.is_empty(), "run `bun run codegen`: stale {stale:?}");
}

#[test]
fn generation_is_deterministic() {
    assert_eq!(vos_codegen::generate(), vos_codegen::generate());
}

/// A colon is not allowed in a Windows file name: no generated file may have one (the module `vos:app` is
/// declared inside one file, not as a file of its own).
#[test]
fn no_generated_file_has_a_colon_in_its_name() {
    for file in vos_codegen::generate().unwrap() {
        assert!(!file.path.contains(':'), "{}", file.path);
    }
}

// ---- the Luau declarations ---------------------------------------------------------------------------------

#[test]
fn the_definitions_declare_the_app_api_and_its_global() {
    let defs = definitions();
    assert!(defs.starts_with("-- GENERATED by vos-codegen"));
    assert!(defs.contains("export type vos_app = {"));
    assert!(defs.contains("\ndeclare app: vos_app\n"), "the global `app`");
    for ty in ["vos_app_Tool", "vos_app_Notification", "vos_app_FileError", "vos_app_FileInfo"] {
        assert!(defs.contains(&format!("export type {ty} =")), "{ty} is defined");
    }
    for ty in ["vos_app_Db", "vos_app_Kv", "vos_app_Files", "vos_app_Location", "vos_app_Context"] {
        assert!(defs.contains(&format!("declare extern type {ty} with\n")), "{ty} is defined");
    }
    assert!(defs.contains("\tfail: (self: vos_app_Context, message: string) -> never\n"));
    // the entry's contract: no function of the module mentions it, the host reads it
    let handlers = vos_lua::declarations::handlers_type();
    let context = vos_lua::declarations::context_type();
    assert!(
        defs.contains(&format!(
            "export type {handlers} = {{ [string]: (ctx: {context}, args: any) -> any }}\n"
        )),
        "{handlers} is defined"
    );
}

/// The members of `app`, by name: what `crates/vos-lua/src/api` installs (its `surface` test holds the same list
/// to the table an app really gets), and nothing a host that drew apps' windows itself offered.
#[test]
fn the_app_api_has_exactly_the_members_the_runtime_installs() {
    let defs = definitions();
    let start = defs.find("export type vos_app = {").unwrap();
    let body = &defs[start..start + defs[start..].find("\n}\n").unwrap()];
    let mut members: Vec<&str> = body
        .lines()
        .filter(|l| l.starts_with('\t') && !l.starts_with("\t\t") && !l.trim_start().starts_with("--"))
        .filter_map(|l| l.trim_start().split_once(':').map(|(name, _)| name))
        .collect();
    members.sort_unstable();
    assert_eq!(
        members,
        ["agents", "db", "emit", "files", "id", "kv", "log", "notify", "open_window", "t", "tool", "tools"]
    );
    let db = defs.find("declare extern type vos_app_Db with").unwrap();
    let db = &defs[db..db + defs[db..].find("\nend\n").unwrap()];
    for gone in ["query:", "row:", "scalar:"] {
        assert!(!db.contains(gone), "db has no live source `{gone}`");
    }
    for gone in
        ["vos_Node", "vos_WindowSpec", "vos_WindowContext", "vos_Manifest", "vos_ui", "vos_ClientDecl"]
    {
        assert!(!defs.contains(gone), "{gone} is gone with the view tree");
    }
    // a failed file call is a typed error: nothing reads a kind back out of a string
    for gone in ["errorKind", "errorMessage"] {
        assert!(!defs.contains(&format!("\t{gone}:")), "{gone} is gone with the error strings");
    }
    assert!(defs.contains("read: (self: vos_app_Location, path: string) -> (string?, vos_app_FileError?)\n"));
}

/// Two `declare require` do not merge: the file has one, and it is the last thing in it.
#[test]
fn the_definitions_have_one_declare_require_with_every_module() {
    let defs = definitions();
    assert_eq!(defs.lines().filter(|l| l.starts_with("declare require")).count(), 1);
    let overloads = vos_codegen::require_overloads(&defs);
    let names: Vec<&str> = overloads.iter().map(|(name, _)| name.as_str()).collect();
    assert!(names.contains(&"vos:app") && !names.contains(&"vos:ui"), "{names:?}");
    assert!(defs.trim_end().ends_with("& ((path: string) -> any)"), "a bundled module of the app is any");
    // `bun run lint:luau` cuts the last section out for its second pass: it must be the last marker of the file
    let last = defs.lines().rfind(|l| l.starts_with("-- ===== ")).unwrap();
    assert_eq!(last, "-- ===== require =====");
    // typed: the app API is the type the file declares
    assert!(overloads.contains(&("vos:app".to_owned(), "vos_app".to_owned())));
}

#[test]
fn the_modules_an_app_is_not_offered_are_unusable_and_the_others_are_the_schemas() {
    let defs = definitions();
    let overloads = vos_codegen::require_overloads(&defs);
    for refused in NOT_FOR_APPS {
        let (_, ty) =
            overloads.iter().find(|(name, _)| name == refused).unwrap_or_else(|| panic!("{refused}"));
        assert!(ty.starts_with("vos_NotForApps_"), "{refused} is typed unusable, not as the module: {ty}");
        let section = format!("-- ===== {refused} =====");
        assert!(!defs.contains(&section), "the section of {refused} is left out");
        assert!(defs.contains(&format!("export type {ty} = {{ __not_for_apps: never }}")), "{ty}");
        // nor is any type of it declared: nothing an app can reach hands one out
        let prefix = format!("{}_", refused.replace(':', "_"));
        assert!(!defs.contains(&format!("export type {prefix}")), "a type of {refused} is declared");
        assert!(!defs.contains(&format!("declare extern type {prefix}")), "a type of {refused} is declared");
    }
    // every other module of the schema keeps its own type (`lib:json` -> `lib_json`) and its section
    let schema = schema();
    assert!(schema.modules.len() > NOT_FOR_APPS.len() + 20);
    for module in &schema.modules {
        if NOT_FOR_APPS.contains(&module.name.as_str()) {
            continue;
        }
        let ty = module.name.replace(':', "_");
        assert!(
            overloads.contains(&(module.name.clone(), ty.clone())),
            "{} keeps its type {ty}",
            module.name
        );
        assert!(
            defs.contains(&format!("-- ===== {} =====\n", module.name)),
            "{} keeps its section",
            module.name
        );
        assert!(defs.contains(&format!("export type {ty} = {{")), "{ty} is declared");
    }
    assert_eq!(overloads.len(), schema.modules.len(), "every module of the schema, offered or refused");
}

#[test]
fn the_globals_an_app_does_not_have_are_declared_unusable() {
    let defs = definitions();
    for global in GLOBALS_NOT_FOR_APPS {
        assert!(defs.contains(&format!("\ndeclare {global}: vos_NotForApps_{global}\n")), "{global}");
    }
    // a function global is unusable by any call (`print("x")`, `pcall(print, "x")`), a library by any member access
    assert!(defs.contains("export type vos_NotForApps_print = (__not_for_apps: never) -> never\n"));
    assert!(defs.contains("export type vos_NotForApps_loadstring = (__not_for_apps: never) -> never\n"));
    assert!(defs.contains("export type vos_NotForApps_os = { __not_for_apps: never }\n"));
    // and none of them is a global the app is meant to use
    for needed in ["app", "typeof", "utf8", "table", "string", "math", "bit32", "coroutine"] {
        assert!(!GLOBALS_NOT_FOR_APPS.contains(&needed), "{needed}");
    }
}

// ---- the TypeScript declarations ---------------------------------------------------------------------------

/// Every module an app is offered is a TypeScript module, and nothing else is: a module or a global an app is not
/// offered is not declared (in TypeScript a name that is not declared is the error).
#[test]
fn the_typescript_declarations_declare_exactly_what_an_app_is_offered() {
    let ts = typescript_declarations();
    let modules: Vec<&str> =
        ts.lines().filter_map(|l| l.strip_prefix("declare module \"")?.strip_suffix("\" {")).collect();
    let offered: Vec<String> = vos_codegen::require_overloads(&definitions())
        .into_iter()
        .filter(|(_, ty)| !ty.starts_with("vos_NotForApps_"))
        .map(|(module, _)| module)
        .collect();
    assert_eq!(modules, offered);
    assert!(modules.contains(&"vos:app") && modules.contains(&"std:fs") && !modules.contains(&"lib:test"));
    assert!(ts.contains("declare const app: typeof import(\"vos:app\")\n"));
    for global in GLOBALS_NOT_FOR_APPS {
        assert!(!ts.contains(&format!("declare const {global}:")), "{global} is declared");
    }
    assert!(!ts.contains("NotForApps"), "{}", "an unusable type is Luau's way to refuse");
}

/// What `TypeScriptToLua` reads to decide how a call is written: a module's function takes `this: void` (called
/// with `.`), a method of a value is an interface's method (called with `:`); a fallible call is a union of tuples.
#[test]
fn the_typescript_declarations_say_how_each_call_is_written() {
    let ts = typescript_declarations();
    for line in [
        "  export function notify(this: void, notification: vos_app_Notification): void\n",
        "  export const db: vos_app_Db\n",
        "  export const t: vos_app_tStatics\n",
        "  string(this: void, options?: vos_app_SchemaOptions): vos_app_Schema\n",
        "  exec(sql: string, params?: { [key: string]: unknown }): vos_app_ExecResult\n",
        "  read(path: string): LuaMultiReturn<[string, undefined] | [undefined, vos_app_FileError]>\n",
        "  run: (this: void, input: unknown, ctx: vos_app_Context) => unknown\n",
        // a call that never returns fits any result: `return ctx.fail("...")` in a handler of any type
        "  fail(message: string): never\n",
        "  export type Context = vos_app_Context\n",
        "  export type Handlers = vos_app_Handlers\n",
    ] {
        assert!(ts.contains(line), "missing {line:?}");
    }
    // nothing is `any`: what has no declared shape is `unknown`, which a backend narrows before it uses it
    assert!(!ts.contains(": any") && !ts.contains("<any>") && !ts.contains("any[]"));
}

// ---- the shell's wire types --------------------------------------------------------------------------------

/// What the shell reads from `types/generated/vos.ts`: every one of these is exported, and nothing of the view
/// protocol is.
#[test]
fn typescript_declares_every_wire_type_the_shell_reads_and_every_method() {
    let ts = vos_codegen::typescript();
    for ty in [
        "JsonValue",
        "SessionHello",
        "SessionWelcome",
        "WindowOpen",
        "AppNotification",
        "AppState",
        "AppWindow",
        "AppSummary",
        "AppList",
        "AppEvent",
        "InstalledInfo",
        "AppPreview",
        "Catalog",
        "DeviceRow",
        "DeviceList",
        "FileEntryKind",
        "FileEntry",
        "FileList",
        "FileLocations",
        "AgentGrantsRow",
        "AgentRow",
        "AgentList",
        "RpcError",
        "MethodName",
    ] {
        assert!(ts.contains(&format!("export type {ty} =")), "{ty}");
    }
    assert!(ts.contains("export const PROTO_VERSION = 1\n"));
    assert!(ts.contains("export const KIT_VERSION = '1.0'\n"));
    assert!(ts.contains("export interface Methods {"));
    for m in METHODS {
        assert!(ts.contains(&format!("'{}': {{ kind:", m.name)), "{}", m.name);
    }
    let summary = ts.find("export type AppSummary").unwrap();
    let summary = &ts[summary..summary + ts[summary..].find("};").unwrap()];
    assert!(!summary.contains("client"), "every app has a page: there is no `client` flag ({summary})");
    for gone in ["ViewSnapshot", "ViewOps", "DataPatch", "COMPONENTS", "'view.", "'row.", "'source."] {
        assert!(!ts.contains(gone), "{gone} is gone with the view protocol");
    }
}
